class UsageBucket(TypedDict):
    creditsUsed: int
    """Credits charged minus credits refunded for these generations. One generation can use several credits."""
    failed: int
    """Failed before any credit was charged."""
    generations: int
    """Generations started in the bucket."""
    key: str
    """The UTC day, API key id or source."""
    pending: int
    """Still running."""
    refunded: int
    """Charged, then refunded."""
    succeeded: int
    """Completed."""


class UsageCounts(TypedDict):
    creditsUsed: int
    """Credits charged minus credits refunded for these generations. One generation can use several credits."""
    failed: int
    """Failed before any credit was charged."""
    generations: int
    """Generations started in the bucket."""
    pending: int
    """Still running."""
    refunded: int
    """Charged, then refunded."""
    succeeded: int
    """Completed."""


# `day`: one bucket per UTC day in the range, including empty days. `key`: per API key id (`none` for calls without a key). `source`: per surface (`mobile`, `api`, `web`, `mcp`, `cli`).
UsageGroupBy: TypeAlias = Literal["day", "key", "source"]


# Live usage of the whole account (every key and surface; test keys are unbilled and not counted), bucketed by when each generation started. Refunds always count against the generation they belong to.
UsageReport = TypedDict(
    "UsageReport",
    {
        "data": List["UsageBucket"],
        "from": str,
        "groupBy": "UsageGroupBy",
        "to": str,
        "totals": "UsageCounts",
    },
)


