# `pending`: queued or retrying. `succeeded`: a 2xx answer. `exhausted`: 8 attempts failed. `failed`: the destination was refused (`blocked_destination`, `invalid_url`) or the secret could not be read. `canceled`: the webhook was disabled before the attempt.
WebhookDeliveryStatus: TypeAlias = Literal["pending", "succeeded", "exhausted", "failed", "canceled"]


# Every webhook event of the contract; narrow on event["type"].
WebhookEvent: TypeAlias = Union["CreditsLowEvent", "GenerationFailedEvent", "GenerationSucceededEvent", "ScreenshotSetCompletedEvent", "WebhookTestEvent"]


# `generation.succeeded`; `generation.failed` (a generation ended `failed` or `canceled`: see `data.status`); `screenshot_set.completed` (a set reached a final status, again after a retry); `credits.low` (live only: the balance fell below `creditsLowThreshold`). `webhook.test` is sent on demand by `POST /webhooks/{id}/test` and needs no subscription.
WebhookEventType: TypeAlias = Literal["generation.succeeded", "generation.failed", "screenshot_set.completed", "credits.low"]


class WebhookGenerationData(TypedDict):
    """The `Generation` at the time of the event, without download URLs."""
    app: "WebhookGenerationDataApp"
    caption: Optional[str]
    """As requested; null = derive."""
    createdAt: str
    """RFC 3339 UTC timestamp."""
    creditsCharged: int
    """1 for live keys, 0 for test keys."""
    creditsRefunded: int
    """Refunded when the generation failed or was canceled before it started."""
    deletedAt: Optional[str]
    """Set by `DELETE`: the result files are gone, this record stays."""
    device: str
    """Catalogue id of the size."""
    environment: "ApiKeyEnvironment"
    error: Optional["WebhookGenerationDataError"]
    """Only when `failed`. See /v1/docs/errors for each code."""
    finishedAt: Optional[str]
    """RFC 3339 UTC timestamp."""
    id: str
    inputs: List["WebhookGenerationDataInputsItem"]
    logo: Optional["WebhookGenerationDataLogo"]
    metadata: Dict[str, str]
    orientation: "Orientation"
    palette: Optional[List["PaletteColor"]]
    """As requested; null = extract from the screenshot."""
    result: Optional["WebhookGenerationDataResult"]
    """As in `GET /generations/{id}` but without URLs (they expire): fetch the generation for fresh ones."""
    screenshotSet: NotRequired["WebhookGenerationDataScreenshotSet"]
    """Present only when this generation is an image of a screenshot set (`POST /screenshot-sets`)."""
    size: "WebhookGenerationDataSize"
    startedAt: Optional[str]
    """RFC 3339 UTC timestamp."""
    status: "GenerationStatus"
    store: "StoreTarget"


class WebhookGenerationDataApp(TypedDict):
    description: str
    name: str


class WebhookGenerationDataError(TypedDict):
    """Only when `failed`. See /v1/docs/errors for each code."""
    code: Literal["GENERATION_FAILED", "GENERATION_TIMEOUT", "NOT_A_SCREENSHOT", "UPLOAD_NOT_READY", "INTERNAL_ERROR"]
    message: str


class WebhookGenerationDataInputsItem(TypedDict):
    sourceUrl: Optional[str]
    """For a URL input: origin and path of the URL (it was imported as `uploadId`)."""
    uploadId: str


class WebhookGenerationDataLogo(TypedDict):
    uploadId: str


class WebhookGenerationDataResult(TypedDict):
    """As in `GET /generations/{id}` but without URLs (they expire): fetch the generation for fresh ones."""
    caption: str
    """The caption used: yours, or the one derived from the screenshot (may be empty)."""
    image: "WebhookGenerationDataResultImage"
    palette: List["PaletteColor"]
    """The colours used."""
    thumbnail: Optional["WebhookGenerationDataResultThumbnail"]


class WebhookGenerationDataResultImage(TypedDict):
    contentType: Literal["image/png", "image/jpeg"]
    """PNG; JPEG for the Google Play feature graphic."""
    height: int
    width: int


class WebhookGenerationDataResultThumbnail(TypedDict):
    contentType: Literal["image/webp"]


class WebhookGenerationDataScreenshotSet(TypedDict):
    """Present only when this generation is an image of a screenshot set (`POST /screenshot-sets`)."""
    attempt: int
    """2 and up: a retry."""
    id: str
    position: int
    """The screen (1-based)."""


class WebhookGenerationDataSize(TypedDict):
    height: int
    width: int


class WebhookList(TypedDict):
    """Webhooks, newest first (at most 10 per environment)."""
    data: List["Webhook"]


class WebhookScreenshotSetData(TypedDict):
    """The `ScreenshotSet` at the time of the event, without `source`, `project` and `preview`."""
    app: "WebhookScreenshotSetDataApp"
    archiveUrl: str
    children: List["WebhookScreenshotSetDataChildrenItem"]
    """The current image of every slot (store, device, screen). Result URLs: `GET /generations?screenshotSetId=` or the archive."""
    counts: "WebhookScreenshotSetDataCounts"
    createdAt: str
    """RFC 3339 UTC timestamp."""
    creditsCharged: int
    """Every image of the set, retries included (0 with a test key)."""
    creditsRefunded: int
    deletedAt: Optional[str]
    """RFC 3339 UTC timestamp."""
    environment: "ApiKeyEnvironment"
    finishedAt: Optional[str]
    """RFC 3339 UTC timestamp."""
    id: str
    images: int
    logo: Optional["WebhookScreenshotSetDataLogo"]
    metadata: Dict[str, str]
    orientation: "Orientation"
    palette: List["PaletteColor"]
    paletteSource: Literal["given", "auto"]
    """`auto`: extracted from screen 1 when the set was created."""
    preview: NotRequired[Optional["ScreenshotSetPreview"]]
    screens: List["WebhookScreenshotSetDataScreensItem"]
    status: "ScreenshotSetStatus"
    stores: List["WebhookScreenshotSetDataStoresItem"]
    updatedAt: str
    """RFC 3339 UTC timestamp."""


class WebhookScreenshotSetDataApp(TypedDict):
    description: str
    name: str


class WebhookScreenshotSetDataChildrenItem(TypedDict):
    attempt: int
    device: str
    error: Optional["WebhookScreenshotSetDataChildrenItemError"]
    featureGraphic: bool
    generationId: str
    position: int
    """The screen (1-based)."""
    size: "WebhookScreenshotSetDataChildrenItemSize"
    status: "GenerationStatus"
    store: "StoreTarget"


class WebhookScreenshotSetDataChildrenItemError(TypedDict):
    code: Literal["GENERATION_FAILED", "GENERATION_TIMEOUT", "NOT_A_SCREENSHOT", "UPLOAD_NOT_READY", "INTERNAL_ERROR"]
    message: str


class WebhookScreenshotSetDataChildrenItemSize(TypedDict):
    height: int
    width: int


class WebhookScreenshotSetDataCounts(TypedDict):
    canceled: int
    failed: int
    queued: int
    running: int
    succeeded: int


class WebhookScreenshotSetDataLogo(TypedDict):
    uploadId: str


class WebhookScreenshotSetDataScreensItem(TypedDict):
    caption: str
    input: "WebhookScreenshotSetDataScreensItemInput"
    position: int


class WebhookScreenshotSetDataScreensItemInput(TypedDict):
    uploadId: str


class WebhookScreenshotSetDataStoresItem(TypedDict):
    devices: List[str]
    featureGraphic: Optional["WebhookScreenshotSetDataStoresItemFeatureGraphic"]
    store: "StoreTarget"


class WebhookScreenshotSetDataStoresItemFeatureGraphic(TypedDict):
    caption: str
    screen: int


class WebhookSecret(TypedDict):
    hint: str
    """The last 4 characters."""
    previousExpiresAt: Optional[str]
    """Until then deliveries are also signed with the previous secret."""
    rotatedAt: Optional[str]
    """RFC 3339 UTC timestamp."""


class WebhookTestEvent(TypedDict):
    apiVersion: str
    created: str
    """RFC 3339 UTC timestamp."""
    data: "WebhookTestEventData"
    environment: "ApiKeyEnvironment"
    id: str
    """Event id (`evt_…`), identical on every attempt: deduplicate on it."""
    type: Literal["webhook.test"]


class WebhookTestEventData(TypedDict):
    message: str
    webhookId: str


class WebhookTestResult(TypedDict):
    deliveryId: str
    eventId: str


class WebhookWithSecret(TypedDict):
    createdAt: str
    """RFC 3339 UTC timestamp."""
    creditsLowThreshold: int
    description: str
    enabled: bool
    environment: "ApiKeyEnvironment"
    events: List["WebhookEventType"]
    id: str
    secret: "WebhookWithSecretSecret"
    updatedAt: str
    """RFC 3339 UTC timestamp."""
    url: str
    """Masked: scheme, host and the last 4 characters of the path."""


class WebhookWithSecretSecret(TypedDict):
    hint: str
    """The last 4 characters."""
    previousExpiresAt: Optional[str]
    """Until then deliveries are also signed with the previous secret."""
    rotatedAt: Optional[str]
    """RFC 3339 UTC timestamp."""
    value: str
    """The signing secret (`whsec_…`). Returned only in this response; store it now. Verify `Storeshot-Signature` with it."""


